import{_ as e,a0 as i,w as p,s as d,I as o,x as n,a1 as s,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"創新的幻覺 | LCTT x X-CMD","titleTemplate":false,"description":"創新的幻覺 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"創新的幻覺 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"創新的幻覺 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190625 The innovation delusion","title":"創新的幻覺","tag":"201907","desc":""},"relativePath":"201907/20190625 The innovation delusion.md","filePath":"[post].md"}'),m={name:"201907/20190625 The innovation delusion.md"};function f(a,t,T,g,w,b){const l=i("Link");return p(),d("div",null,[t[44]||(t[44]=o("h1",{id:"創新的幻覺",tabindex:"-1"},[n("創新的幻覺 "),o("a",{class:"header-anchor",href:"#創新的幻覺","aria-label":"Permalink to “創新的幻覺”"},"​")],-1)),t[45]||(t[45]=o("blockquote",null,[o("p",null,"創新是一種混亂的過程，但是關於創新的故事卻很有條理。我們不應該把兩者搞混了。")],-1)),t[46]||(t[46]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/16/120302zlyzlzl2d2vh1eyd.jpg",alt:""})],-1)),o("p",null,[t[1]||(t[1]=n("如果説 ",-1)),s(l,{href:"https://www.youtube.com/watch?v=8MCbJmZQM9c"},{default:r(()=>[...t[0]||(t[0]=[n("傳統的規劃方法已經消亡了",-1)])]),_:1}),t[2]||(t[2]=n("，為什麼這麼多機構還在孜孜不倦地運用那些針對工業革命所設計的規劃方法呢？",-1))]),t[47]||(t[47]=u('<p>其中的一個原因是，我們錯誤地認為創新是可以通過結構化的、線性的過程實現的。我覺得這樣做是在混淆關於創新的 <strong>故事</strong> 和創新這個 <strong>過程</strong> 本身 —— 兩者是截然不同的東西。</p><p>創新的過程是混亂和不可預測的，並不遵循井然有序的時間線。過程中充滿了重複迭代、突然的改變方向、各式各樣的啓動和終止、死衚衕、失敗（但願是有用的失敗），以及很多不可知的變量。創新是混亂的。</p><p>但是關於創新的故事卻讓事情顯得很簡單，從講述偉大發明的書籍和文章，到我們（簡化了整個過程之後）講述自己在工作上的成功都是這樣。想想你在社交媒體上讀的帖子裏，有多少都只寫了最好的、最愉快的部分吧。</p><p>好故事就是這樣。我們把一些原本分散的時間點乾淨利落地整理到一起，有開頭、有發展、也有結尾。儘管我們一路上經歷了很多沒有把握、恐慌、甚至是絕望的時刻，在故事裏這些坎坷卻都被抹平了，讓事情看起來像是從一開始就註定是成功的。</p><p>我們不應該把混亂的過程和簡化了的故事搞混。否則，我們會錯誤地認為可以使用在簡單線性過程中所使用的同樣的方法迎接創新的挑戰。換句話説，我們將適用於一種類型的活動（比較偏死記硬背、機械和規則性的任務）的管理技術應用在了並不適用的另一種類型的活動（更加有創造性的、非線性的工作，需要自主性和試驗）上。</p><h3 id="一個創新的故事" tabindex="-1">一個創新的故事 <a class="header-anchor" href="#一個創新的故事" aria-label="Permalink to “一個創新的故事”">​</a></h3>',6)),o("p",null,[t[4]||(t[4]=n("下面這個故事可以很好地説明這一點。這是我 ",-1)),s(l,{href:"https://www.youtube.com/watch?v=8MCbJmZQM9c"},{default:r(()=>[...t[3]||(t[3]=[n("最喜歡舉的例子",-1)])]),_:1}),t[5]||(t[5]=n(" 之一。",-1))]),t[48]||(t[48]=o("p",null,"在 1970 年代，英國的摩托車行業怎麼也想不明白為什麼他們在美國的市場份額急劇下降，而本田公司的市場份額卻急速攀升。他們僱傭了波士頓諮詢公司（剛好是我之前的僱主）幫助他們找出問題所在。波士頓諮詢蒐集了一些歷史數據，回看了二十年的歷史事件，總結出了一個井井有條的、線性的故事，可以很好地解釋本田公司的成功。",-1)),o("p",null,[s(l,{href:"https://assets.publishing.service.gov.uk/government/uploads/system/uploads/attachment_data/file/235319/0532.pdf"},{default:r(()=>[...t[6]||(t[6]=[n("波士頓諮詢的結論是",-1)])]),_:1}),t[7]||(t[7]=n("，本田公司使用了一個巧妙的策略：通過一種可以以更低價格銷售的偏小型摩托車進入美國市場，並且藉助於他們在日本本土市場發展出來的規模經濟，在美國市場使用低價策略發展市場份額，然後等到需求進一步增長的時候，再利用更大的規模經濟發展他們在美國的市場份額。在所有人的眼中，本田公司都表現得非常出色，不僅發揮了自己的優勢，還非常透徹和精準地理解了新的目標顧客：美國消費者。他們智勝一籌，通過一個執行得很好的計劃佔領了先機，勝過了競爭對手們。",-1))]),t[49]||(t[49]=o("p",null,[n("這個故事 "),o("strong",null,"聽上去"),n(" 很厲害，但是實際情況沒有這麼簡單。")],-1)),o("p",null,[t[9]||(t[9]=n("沒錯，本田公司 ",-1)),t[10]||(t[10]=o("strong",null,"確實",-1)),t[11]||(t[11]=n(" 是想進入美國摩托車市場。他們最初是想 ",-1)),s(l,{href:"http://www.howardyu.org/the-revolutionary-approach-honda-took-to-rise-above-competition/"},{default:r(()=>[...t[8]||(t[8]=[n("效仿在美國的競爭對手",-1)])]),_:1}),t[12]||(t[12]=n("，也製造美國人似乎更喜歡的大型摩托車。但是大型摩托車並不是本田公司的強項，他們生產的大型摩托車存在可靠性上的問題。更糟的是，他們的產品和市面上的其它產品沒有什麼差別，所以並不能脱穎而出。簡單來説，他們的產品銷售額表現平平。",-1))]),t[50]||(t[50]=o("p",null,"但是在一次奇妙的巧合裏，本田公司出訪美國的日本代表們帶了幾輛自己開的摩托車。這些摩托車和本田公司試圖在美國市場上銷售的摩托車完全不同，它們更為小巧靈活、不那麼笨重、更有效率，並且一般來説也更便宜。西爾斯公司（LCTT 譯註：美國零售業巨頭）注意到了這些小巧的摩托車，並且和日本代表達成了一項協議，讓西爾斯公司可以在他們在美國的商店裏出售這種被稱為“超級幼獸”的新型摩托車。",-1)),o("p",null,[t[15]||(t[15]=n("剩下的故事已經載入史冊。超級幼獸成為了 ",-1)),s(l,{href:"https://autoweek.com/article/motorcycles/first-ride-honda-super-cub-c125-abs-all-new-and-still-super-cute"},{default:r(()=>[...t[13]||(t[13]=[n("史上最暢銷的機動車",-1)])]),_:1}),t[16]||(t[16]=n("，並且本田公司 ",-1)),s(l,{href:"https://www.autoblog.com/2019/02/13/2019-honda-super-cub-first-ride-review/"},{default:r(()=>[...t[14]||(t[14]=[n("至今仍然在生產超級幼獸",-1)])]),_:1}),t[17]||(t[17]=n("。",-1))]),t[51]||(t[51]=u('<p>事後看來，將超級幼獸帶到美國的一連串事件似乎很有邏輯，近乎無聊了。但是本田公司的成功和“巧妙的計劃”沒有什麼關係，而更應該歸功於一些（大多數人不願意承認的）機緣巧合。</p><h3 id="開放-並且混亂的-創新" tabindex="-1">開放（並且混亂的）創新 <a class="header-anchor" href="#開放-並且混亂的-創新" aria-label="Permalink to “開放（並且混亂的）創新”">​</a></h3><p>機構（特別是領導們）喜歡把成功説成是一件計劃之內的事情 —— 好像成功人士可以駕馭混亂，並且幾乎可以預測未來。但是這些言論都是事後諸葛亮罷了，他們在講述自己充滿偶然性的經歷的時候會刻意將無序的事情整理一番，對於毫無確定性的事情也會説“我們就是想要那麼做的”。</p><p>但是正如我前面説的，我們不應該相信這些故事是創新過程的真實還原，也不應該在這種錯誤的假設的基礎之上去構建未來的方案或者實驗。</p><p>試想有另一家摩托車製造商想要複製本田公司在超級幼獸上的成功，就逐字逐句地照搬波士頓諮詢總結的故事。由於本田公司成功的 <strong>故事</strong> 聽上去是如此有邏輯，並且是線性的，這家新公司也許會假定他們可以通過類似的程序得到同樣的結果：制定目標、謀劃行動，然後針對可預期的結果進行執行。但是我們知道本田公司並不是真的靠這種“制定、謀劃、執行”的方式贏得他們的市場份額的。他們是通過靈活性和一點運氣獲得成功的 —— 更像是“嘗試、學習、修改”。</p><p>當我們可以真正理解並且接受“創新過程是混亂的”這個事實的時候，我們就可以換種方式思考如何讓我們的機構實現創新了。與其將資源浪費在預先制定的計劃上，<strong>強迫</strong> 創新以一種線性時間線的方式發生，我們不如去構建一些開放並且敏捷的機構，可以 <strong>在創新發生的時候做出及時的響應</strong>。</p>',6)),o("p",null,[t[19]||(t[19]=n("幾年前紅帽公司發佈一個包含了重大技術升級的產品的新版本的時候，我就看到了這樣的方法。",-1)),s(l,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/5/html/5.4_release_notes/index"},{default:r(()=>[...t[18]||(t[18]=[n("紅帽企業級 Linux 5.4 版本",-1)])]),_:1}),t[20]||(t[20]=n(' 首次完全支持了一種被稱為"基於內核的虛擬機"（KVM）的技術。這對於我們來説是一個重大的創新，不僅可以為顧客和合作夥伴帶來巨大的價值，也有望為開源社區帶來巨大的價值。',-1))]),t[52]||(t[52]=o("p",null,"這項技術正在快速演進。幸運的事，因為我們是一個開放的機構，我們具有足夠的適應能力，可以在這項創新發生的時候做出響應，從而幫助我們的顧客和合作夥伴可以更好地利用它。這項技術太重要了，並且競爭格局也太不穩定了，以至於我們沒有理由要等到像 6.0 版本這樣的里程碑時刻才出手。",-1)),o("p",null,[t[22]||(t[22]=n("如果你回看紅帽企業級 Linux ",-1)),s(l,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/5/html/5.0_release_notes/index"},{default:r(()=>[...t[21]||(t[21]=[n("已經存檔的發行説明",-1)])]),_:1}),t[23]||(t[23]=n("，你會發現它讀起來並不像一個典型的軟件創新的故事。一次改變遊戲規則的進展突然出現在一個沒有預測到的、並不起眼的時刻（5.4 版本），而不是一個事先計劃好的重要里程碑時刻（6.0 版本）。事後看來，我們現在知道 KVM 這種“大爆炸”級別的進步是足夠擔得起 “6.0 版本”這樣的里程碑式的名字的。但是創新並不是按照這樣的劇本發生的。",-1))]),o("p",null,[t[26]||(t[26]=n("不要誤解我，機構仍然需要保持出色的運轉，高效完成執行性的任務。但是 ",-1)),s(l,{href:"https://opensource.com/open-organization/19/4/managed-enabled-empowered"},{default:r(()=>[...t[24]||(t[24]=[n("不同的挑戰需要不同的方法去應對",-1)])]),_:1}),t[27]||(t[27]=n("，我們需要能夠更好地建立靈活的機構，以及對 ",-1)),s(l,{href:"https://www.linkedin.com/pulse/how-plan-world-full-unknowns-jim-whitehurst/"},{default:r(()=>[...t[25]||(t[25]=[n("意想不到和不可知的事情",-1)])]),_:1}),t[28]||(t[28]=n(" 能夠做出更好的響應。",-1))]),t[53]||(t[53]=o("p",null,"一個在計劃工作（以及按照計劃執行）上做得很出色的公司很可能會得到他們計劃要得到的結果。但是如果成功還取決於我們沒有預測或者無法預測的的事情，那麼僅僅精準地按照計劃執行是不是就不夠了？",-1)),t[54]||(t[54]=o("hr",null,null,-1)),o("p",null,[t[30]||(t[30]=n("via: ",-1)),s(l,{href:"https://opensource.com/open-organization/19/6/innovation-delusion"},{default:r(()=>[...t[29]||(t[29]=[n("https://opensource.com/open-organization/19/6/innovation-delusion",-1)])]),_:1})]),o("p",null,[t[35]||(t[35]=n("作者：",-1)),s(l,{href:"https://opensource.com/users/jwhitehurst/users/jwhitehurst/users/n8chz/users/dhdeans"},{default:r(()=>[...t[31]||(t[31]=[n("Jim Whitehurst",-1)])]),_:1}),t[36]||(t[36]=n(" 選題：",-1)),s(l,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[32]||(t[32]=[n("lujun9972",-1)])]),_:1}),t[37]||(t[37]=n(" 譯者：",-1)),s(l,{href:"https://github.com/chen-ni"},{default:r(()=>[...t[33]||(t[33]=[n("chen-ni",-1)])]),_:1}),t[38]||(t[38]=n(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[34]||(t[34]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[41]||(t[41]=n("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[39]||(t[39]=[n("LCTT",-1)])]),_:1}),t[42]||(t[42]=n(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:r(()=>[...t[40]||(t[40]=[n("Linux中國",-1)])]),_:1}),t[43]||(t[43]=n(" 榮譽推出",-1))])])}const k=e(m,[["render",f]]);export{v as __pageData,k as default};
